const $=s=>document.querySelector(s),names=Bamboo.names;
const desc=['经纬竹篾交替挑压，在方正之间建立最质朴的秩序。','三向竹篾交织，形成通透的六角结构意象。','以细篾穿入基础经纬，增加疏密与线条层次。','斜向交错连续排列，形成如人字起伏的节奏。','以三向线条构建细密的三角孔几何韵律。'];
const fixed=[['墨竹鎏金','#bda16b','#76603b','#111613'],['竹青本色','#b9c18b','#68734a','#20271c'],['素篾米白','#dcd3b7','#9b9076','#393e32'],['朱砂墨韵','#c66f52','#977847','#251917']];
const painting=[['青绿山水','#739589','#b69b62','#172d29'],['水墨留白','#93978a','#c8c4b3','#242b27'],['赭石秋山','#b9875b','#807347','#24271d'],['荷塘清趣','#b89595','#728a68','#202a25']];
const objects=[['tote','手提包','把山野，带在身边。','经纬交织的随行手提包，让东方纹样融入每一次出发。'],['vase','瓷器','一器之间，盛下风雅。','以温润器型承载交织纹样，探索竹与瓷相遇的美感。'],['phone','手机壁纸','方寸屏幕，自有天地。','让竹编的秩序成为每日可见的风景。'],['fan','团扇','一扇清风，轻织夏意。','将经纬之美融入圆形扇面，留住一缕东方清凉。'],['bookmark','书签','书页之间，竹影悠长。','以一枚纤长书签，将阅读与手艺轻轻相连。']];
let state={type:0,density:20,width:7,offsetX:0,offsetY:0,a:fixed[0][1],b:fixed[0][2],bg:fixed[0][3],palette:fixed[0][0],mode:'fixed',object:0};
try{const saved=JSON.parse(localStorage.getItem('zhuxu-design'));if(saved&&Number.isInteger(saved.type)&&saved.type>=0&&saved.type<5&&[saved.a,saved.b,saved.bg].every(c=>/^#[0-9a-f]{6}$/i.test(c)))state={...state,...saved};}catch{}
function svg(){return Bamboo.pattern(state.type,{spacing:640/state.density,width:state.width,x:state.offsetX,y:state.offsetY,a:state.a,b:state.b,bg:state.bg})}
function render(){ $('#livePattern').innerHTML=svg();$('#liveSummary').textContent=names[state.type]+' · '+state.palette;$('#patternCode').textContent=['CROSS','HEXAGON','THREAD','HERRINGBONE','TRIANGLE'][state.type]+' / 0'+(state.type+1);$('#methodDescription').textContent=desc[state.type];document.querySelectorAll('#methods button').forEach((b,i)=>{b.classList.toggle('active',i===state.type);b.setAttribute('aria-pressed',String(i===state.type))});['density','width','offsetX','offsetY'].forEach(k=>{$('#'+k).value=state[k];$('#'+k+'Value').value=state[k]});$('#colorA').value=state.a;$('#colorB').value=state.b;$('#colorBg').value=state.bg;}
function palettes(){const list=state.mode==='fixed'?fixed:painting;$('#palettes').innerHTML=list.map((p,i)=>`<button class="palette ${p[0]===state.palette?'active':''}" data-palette="${i}"><span class="swatches"><i style="background:${p[1]}"></i><i style="background:${p[2]}"></i><i style="background:${p[3]}"></i></span>${p[0]}</button>`).join('');$('#paintingTools').hidden=state.mode!=='painting';document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));document.querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>{const p=list[+b.dataset.palette];[state.palette,state.a,state.b,state.bg]=p;palettes();render()})}
$('#heroPattern').innerHTML=Bamboo.pattern(0,{spacing:25,width:11,a:'#c7ad73',b:'#8d7346',bg:'#252719'});
$('#patternCards').innerHTML=names.map((n,i)=>`<button class="pattern-card" data-method="${i}" aria-label="选择${n}并进入工坊"><div class="pattern-picture">${Bamboo.pattern(i,{spacing:45,width:10})}</div><h3>${n}<span class="arrow">↗</span></h3><small>0${i+1} / ${['CROSS WEAVE','HEXAGON WEAVE','THREADED WEAVE','HERRINGBONE','TRIANGULAR WEAVE'][i]}</small></button>`).join('');
$('#methods').innerHTML=names.map((n,i)=>`<button data-method="${i}">${n}</button>`).join('');document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{state.type=+b.dataset.method;render();if(b.classList.contains('pattern-card'))$('#studio').scrollIntoView({behavior:'smooth'})});
['density','width','offsetX','offsetY'].forEach(k=>$('#'+k).oninput=e=>{state[k]=+e.target.value;render()});[['colorA','a'],['colorB','b'],['colorBg','bg']].forEach(([id,k])=>$('#'+id).oninput=e=>{state[k]=e.target.value;state.palette='自定义配色';render();palettes()});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;palettes()});
$('#tryPainting').onclick=()=>{state.mode='painting';palettes();$('#studio').scrollIntoView({behavior:'smooth'})};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
$('#save').onclick=()=>{try{localStorage.setItem('zhuxu-design',JSON.stringify(state));toast('方案已保存在当前浏览器，下次打开自动恢复')}catch{toast('浏览器存储不可用，请导出纹样保存')}};
$('#reset').onclick=()=>{state={type:0,density:20,width:7,offsetX:0,offsetY:0,a:fixed[0][1],b:fixed[0][2],bg:fixed[0][3],palette:fixed[0][0],mode:'fixed',object:0};render();palettes();renderObject();toast('已恢复初始设计')};
function download(blob,name){let a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('#export').onclick=()=>{download(new Blob([svg()],{type:'image/svg+xml'}),`竹序-${names[state.type]}-${state.palette}.svg`);toast('已导出可编辑的矢量纹样')};
function renderObject(){if(![0,2,3,4].includes(state.object))state.object=0;let o=objects[state.object];$('#mockObject').className='mock-object '+o[0];$('#objectTitle').textContent=o[2];$('#objectDesc').textContent=o[3];$('#objectNumber').textContent='OBJECT / 0'+([0,2,3,4].indexOf(state.object)+1);document.querySelectorAll('[data-object]').forEach((b,i)=>{b.classList.toggle('active',+b.dataset.object===state.object);b.setAttribute('aria-pressed',String(+b.dataset.object===state.object))})}
$('#objectTabs').innerHTML=objects.map((o,i)=>`<button data-object="${i}">${o[1]}</button>`).join('');document.querySelectorAll('[data-object]').forEach(b=>b.onclick=()=>{state.object=+b.dataset.object;renderObject()});
$('#upload').onchange=async e=>{let file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('请选择图片文件');let url=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{let c=document.createElement('canvas');c.width=c.height=80;let ctx=c.getContext('2d');ctx.drawImage(img,0,0,80,80);let px=ctx.getImageData(0,0,80,80).data,bins={};for(let i=0;i<px.length;i+=4){if(px[i+3]<128)continue;let rgb=[px[i],px[i+1],px[i+2]].map(v=>Math.min(255,Math.round(v/32)*32));let key=rgb.join(',');bins[key]=(bins[key]||0)+1}let colors=Object.entries(bins).sort((a,b)=>b[1]-a[1]).slice(0,12).map(([s])=>s.split(',').map(Number));if(colors.length<1)throw Error();colors.sort((a,b)=>a.reduce((x,y)=>x+y)-b.reduce((x,y)=>x+y));let hex=c=>'#'+c.map(n=>n.toString(16).padStart(2,'0')).join('');state.bg=hex(colors[0]);state.a=hex(colors[colors.length-1]);state.b=hex(colors[Math.floor(colors.length/2)]);state.palette='图片提取';if(typeof changed==='function')changed();else render();palettes();toast('已从图片提取深、中、浅三组代表色')}catch{toast('图片读取失败，请换一张图片')}finally{URL.revokeObjectURL(url)}};img.onerror=()=>{URL.revokeObjectURL(url);toast('不支持此图片，请使用 JPG 或 PNG')};img.src=url;};
$('#exportMock').onclick=()=>{let c=document.createElement('canvas');c.width=1200;c.height=1000;let x=c.getContext('2d'),im=new Image(),url=URL.createObjectURL(new Blob([svg()],{type:'image/svg+xml'}));im.onload=()=>{x.fillStyle='#1b2019';x.fillRect(0,0,1200,1000);let t=objects[state.object][0];x.save();x.fillStyle='#c6bea5';if(t==='tote'){x.strokeStyle='#8a7956';x.lineWidth=22;x.beginPath();x.arc(600,260,95,Math.PI,0);x.stroke();x.beginPath();x.roundRect(390,250,420,430,[8,8,60,60]);}else if(t==='phone'){x.beginPath();x.roundRect(440,160,320,640,45);}else if(t==='bookmark'){x.beginPath();x.rect(510,170,180,610);}else if(t==='fan'){x.fillStyle='#a58e62';x.fillRect(586,590,28,220);x.beginPath();x.arc(600,390,230,0,Math.PI*2);}else{x.beginPath();let p=[[550,170],[650,170],[640,290],[740,460],[770,590],[720,730],[480,730],[430,590],[460,460],[560,290]];p.forEach(([a,b],i)=>i?x.lineTo(a,b):x.moveTo(a,b));x.closePath()}x.fill();x.clip();if(t==='phone'||t==='fan')x.drawImage(im,350,150,500,650);else x.drawImage(im,380,355,440,250);x.restore();x.fillStyle='#c0a575';x.textAlign='center';x.font='30px serif';x.fillText('竹 序 · '+objects[state.object][1],600,880);x.font='16px sans-serif';x.fillText(names[state.type]+' / '+state.palette+' / 平面概念套样',600,925);URL.revokeObjectURL(url);c.toBlob(b=>{if(b)download(b,'竹序-'+objects[state.object][1]+'-套样.png')});toast('套样图已导出')};im.onerror=()=>{URL.revokeObjectURL(url);toast('导出失败，请重试')};im.src=url;};render();palettes();renderObject();
